### Repro steps

If a hook has a parameter that's supposed to be a function, the hook behavior becomes unexpected. In the provided example (see playground link), if we inline the `namespace` variable like this:

```js
// Input
function useTranslate(getNamespace) {
  const messages = useMessages();
  const formatIcu = useIcuFormatter();

  return createTranslateFunction(getNamespace(messages), formatIcu);
}
```

```js
// Output
import { c as _c } from "react/compiler-runtime";
function useTranslate(getNamespace) {
  const $ = _c(4);
  const messages = useMessages();
  const formatIcu = useIcuFormatter();
  let t0;
  if ($[0] !== formatIcu || $[1] !== getNamespace || $[2] !== messages) {
    t0 = createTranslateFunction(getNamespace(messages), formatIcu);
    $[0] = formatIcu;
    $[1] = getNamespace;
    $[2] = messages;
    $[3] = t0;
  } else {
    t0 = $[3];
  }
  return t0;
}

```

the output seems to be almost correct: it memoizes most of the things, however it doesn't memoize `getNamespace(messages)` into its own variable (maybe that's another issue or even a non-issue altogether, I'm not sure, still reported it in #36848), however if we inline all of the variables like this:

```js
function useTranslate(getNamespace) {
  return createTranslateFunction(getNamespace(useMessages()), useIcuFormatter());
}
```

the ouput again doesn't memoize anything

