  {"second":1,"mapSize":1397,"retainedAncestryNodes":132464,"maxChainDepth":131070,"rssMB":169}
  {"second":3,"mapSize":392992,"retainedAncestryNodes":711602,"maxChainDepth":318614,"rssMB":412}
